"""Minimal SMILES graph parser + WL hash, stdlib only, for analysis."""
import re
from collections import Counter

ORGANIC = {'B': 3, 'C': 4, 'N': 3, 'O': 2, 'P': 3, 'S': 2, 'F': 1, 'Cl': 1, 'Br': 1, 'I': 1}
AROMATIC = {'b': 'B', 'c': 'C', 'n': 'N', 'o': 'O', 'p': 'P', 's': 'S'}
BRACKET = re.compile(r'\[([^\]]+)\]')
ATOM = re.compile(r'(\[[^\]]+\]|Cl|Br|[BCNOPSFIbcnops]|\*|%\d{2}|\d|[=#:/\\.()\-])')


def parse(smiles):
    """Return (atoms, bonds): atoms = list of invariant tuples, bonds = list of (i,j,order)."""
    tokens = ATOM.findall(smiles)
    atoms = []
    bonds = []
    stack = []
    rings = {}
    prev = None
    pending = 1
    for tok in tokens:
        if tok in '-/\\':
            pending = 1
        elif tok == '=':
            pending = 2
        elif tok == '#':
            pending = 3
        elif tok == ':':
            pending = 4
        elif tok == '(':
            stack.append(prev)
        elif tok == ')':
            prev = stack.pop()
        elif tok.isdigit() or tok.startswith('%'):
            num = int(tok[1:]) if tok.startswith('%') else int(tok)
            if num in rings:
                other, order = rings.pop(num)
                bonds.append((other, len(atoms) - 1, order if order else pending))
            else:
                rings[num] = (len(atoms) - 1, pending)
            pending = 1
        else:
            aromatic = tok.islower() and len(tok) == 1
            if tok.startswith('['):
                body = tok[1:-1]
                m = re.match(r'(\d+)?([A-Za-z][a-z]?|\*)(@{1,2}(?:TH|AL|SP|TB|OH)?)?(H\d*)?([+-]\d*)?', body)
                isotope = int(m.group(1)) if m.group(1) else 0
                symbol = m.group(2)
                aromatic = symbol.islower() and len(symbol) == 1
                if aromatic:
                    symbol = AROMATIC.get(symbol, symbol.upper())
                hs = m.group(4)
                hcount = (int(hs[1:]) if hs and len(hs) > 1 else 1) if hs else 0
                charge_txt = m.group(5) or ''
                if charge_txt in ('+', '-'):
                    charge = 1 if charge_txt == '+' else -1
                elif charge_txt:
                    sign = 1 if charge_txt[0] == '+' else -1
                    digits = charge_txt[1:]
                    charge = sign * (int(digits) if digits else 1)
                else:
                    charge = 0
                atoms.append((symbol, float(hcount), charge, isotope, 1 if aromatic else 0))
            else:
                if aromatic:
                    atoms.append((AROMATIC[tok], 0.0, 0, 0, 1))
                else:
                    atoms.append((tok, 0.0, 0, 0, 0))
            idx = len(atoms) - 1
            if prev is not None:
                bonds.append((prev, idx, pending))
            prev = idx
            pending = 1
    return atoms, bonds


def _invariant(atom):
    symbol, h, charge, isotope, aromatic = atom
    return (symbol, h, charge, isotope, aromatic)


def wl_hash(smiles, rounds=8):
    """Weisfeiler-Lehman hash of the molecular graph (stereo ignored except as flag)."""
    atoms, bonds = parse(smiles)
    if not atoms:
        return None
    adjacency = {i: [] for i in range(len(atoms))}
    for i, j, order in bonds:
        if i == j:
            continue
        adjacency[i].append((j, order))
        adjacency[j].append((i, order))
    labels = [_invariant(a) for a in atoms]
    for _ in range(rounds):
        new = []
        for i in range(len(atoms)):
            neigh = sorted((order, repr(labels[j])) for j, order in adjacency[i])
            new.append((repr(labels[i]), tuple(neigh)))
        labels = new
    return tuple(sorted(repr(x) for x in labels))


def components(smiles):
    return [c for c in re.split(r'\.', smiles.strip()) if c.strip()]


def mol_key(component):
    return wl_hash(component.strip().lower())


def is_same_mol(a, b):
    return mol_key(a) == mol_key(b) and mol_key(a) is not None

