"""Minimal SMILES graph parser + WL hash, stdlib only, for analysis."""
import re

ORGANIC = {'B': 3, 'C': 4, 'N': 3, 'O': 2, 'P': 3, 'S': 2, 'F': 1, 'Cl': 1, 'Br': 1, 'I': 1}
AROMATIC = {'b': 'B', 'c': 'C', 'n': 'N', 'o': 'O', 'p': 'P', 's': 'S'}
ATOM = re.compile(r'(\[[^\]]+\]|Cl|Br|[BCNOPSFIbcnops]|%\d{2}|\d|[=#:/\\.()\-])')


def parse(smiles):
    tokens = ATOM.findall(smiles)
    atoms = []          # (symbol, hcount, charge, isotope, aromatic)
    bonds = []
    stack = []
    rings = {}
    prev = None
    pending = 1
    for tok in tokens:
        if tok in '-/\\':
            pending = 1
        elif tok == '=':
            pending = 2
        elif tok == '#':
            pending = 3
        elif tok == ':':
            pending = 4
        elif tok == '(':
            stack.append(prev)
        elif tok == ')':
            prev = stack.pop()
        elif tok.isdigit() or tok.startswith('%'):
            num = int(tok[1:]) if tok.startswith('%') else int(tok)
            if num in rings:
                other, order = rings.pop(num)
                bonds.append((other, len(atoms) - 1, order))
            else:
                rings[num] = (len(atoms) - 1, pending)
            pending = 1
        else:
            aromatic = tok.islower() and len(tok) == 1
            if tok.startswith('['):
                body = tok[1:-1]
                m = re.match(r'(\d+)?([A-Za-z][a-z]?|\*)(@{1,2}(?:TH|AL|SP|TB|OH)?)?(H\d*)?([+-]\d*)?', body)
                isotope = int(m.group(1)) if m.group(1) else 0
                symbol = m.group(2)
                aromatic = symbol.islower() and len(symbol) == 1
                if aromatic:
                    symbol = AROMATIC.get(symbol, symbol.upper())
                hs = m.group(4)
                hcount = (int(hs[1:]) if hs and len(hs) > 1 else 1) if hs else 0
                charge_txt = m.group(5) or ''
                if charge_txt in ('+', '-'):
                    charge = 1 if charge_txt == '+' else -1
                elif charge_txt:
                    sign = 1 if charge_txt[0] == '+' else -1
                    digits = charge_txt[1:]
                    charge = sign * (int(digits) if digits else 1)
                else:
                    charge = 0
                atoms.append((symbol, float(hcount), charge, isotope, 1 if aromatic else 0))
            else:
                symbol = AROMATIC[tok] if aromatic else tok
                atoms.append((symbol, None, 0, 0, 1 if aromatic else 0))
            idx = len(atoms) - 1
            if prev is not None:
                bonds.append((prev, idx, pending))
            prev = idx
            pending = 1
    # implicit hydrogens for organic-subset atoms
    valence = {i: 0 for i in range(len(atoms))}
    for i, j, order in bonds:
        if i == j:
            continue
        valence[i] += order
        valence[j] += order
    filled = []
    for i, (symbol, hcount, charge, isotope, aromatic) in enumerate(atoms):
        if hcount is None:
            target = ORGANIC.get(symbol, 0) + (1 if aromatic and symbol in ('C', 'N') else 0)
            target = ORGANIC.get(symbol, 0)
            hcount = max(0, target - valence[i])
        filled.append((symbol, float(hcount), charge, isotope, aromatic))
    return filled, bonds


def _hash(smiles, rounds, relaxed):
    atoms, bonds = parse(smiles)
    if not atoms:
        return None
    adjacency = {i: [] for i in range(len(atoms))}
    for i, j, order in bonds:
        if i == j:
            continue
        adjacency[i].append((j, order))
        adjacency[j].append((i, order))
    labels = []
    for symbol, h, charge, isotope, aromatic in atoms:
        labels.append((symbol, h, charge, isotope, 0 if relaxed else aromatic))
    ids = _compress(labels)
    for _ in range(rounds):
        signatures = []
        for i in range(len(atoms)):
            neigh = tuple(sorted((order, ids[j]) for j, order in adjacency[i]))
            signatures.append((ids[i], neigh))
        ids = _compress(signatures)
    return tuple(sorted(ids))


def _compress(pairs):
    order = {value: rank for rank, value in enumerate(sorted(set(map(repr, pairs)), key=str))}
    return [order[repr(value)] for value in pairs]


def mol_key(component, relaxed=False):
    return _hash(component.strip(), 8, relaxed)


def is_same_mol(a, b):
    if a.strip().lower() == b.strip().lower():
        return True
    ka, kb = mol_key(a), mol_key(b)
    if ka is not None and ka == kb:
        return True
    return mol_key(a, True) == mol_key(b, True)


def components(smiles):
    return [c for c in re.split(r'\.', (smiles or '').strip()) if c.strip()]

